"""R14 §6 — every table of the report, generated from the run outputs (nothing is typed by hand): preconditions (+ git status of
phase4/ after the directive), coarsened grids, native-level checks, the GBT fold-model reproduction check, the main table (primary),
the per-pair table, the main table and views (secondary), and the §1 expectations evaluated under their exact definitions.
Reads R14/tables/preconditions.json, <COARSE>/coarse_record.json, <PRED>/predictors_record.json, <TGT>/targets_record.json,
<GBT>/record.json, <SCORES>/results.json, <SCORES>/per_pair.csv. Writes R14/tables/*.md and tables.json. Read-only; no guard needed
(no raster or sealed path is opened; only R14 JSON / CSV outputs)."""
import json, os, subprocess, sys
import numpy as np, pandas as pd
DR = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); REPO = os.path.dirname(os.path.dirname(DR))
ROOT = "/scratch/users/scdobbs/grl_review/R14"; TABLES = f"{DR}/R14/tables"; LEVELS = (8.0, 4.0, 3.0, 2.1, 1.7); KEYS = ["frozen", "native"] + [f"c{c}" for c in LEVELS]
LABEL = {"frozen": "native (frozen R10b columns)", "native": "native (R14 recomputed)", **{f"c{c}": f"{c:g}" for c in LEVELS}}

def git(*a): return subprocess.run(["git", *a], cwd=REPO, capture_output=True, text=True).stdout.strip()
def f3(v, sign=True):
    if v is None or (isinstance(v, float) and not np.isfinite(v)): return "—"
    return f"{v:+.3f}" if sign else f"{v:.3f}"
def ci(row, lo, hi): return f"[{f3(row.get(lo))}, {f3(row.get(hi))}]" if row.get(lo) is not None and np.isfinite(row.get(lo, np.nan)) else "[—, —]"
def pooled_str(p):
    if not p: return "—"
    return f"{f3(p['mean_rho'])} {('[' + f3(p['ci95'][0]) + ', ' + f3(p['ci95'][1]) + ']') if p['estimable'] else '[not estimable]'}"
def md(rows, header): return "\n".join(["| " + " | ".join(header) + " |", "|" + "---|" * len(header)] + ["| " + " | ".join(str(x) for x in r) + " |" for r in rows])
def write(name, text, comment): open(f"{TABLES}/{name}", "w").write(f"<!-- generated by report_tables_r14.py {comment} -->\n{text}\n")

if __name__ == "__main__":
    os.makedirs(TABLES, exist_ok=True); out = {}
    pre = json.load(open(f"{TABLES}/preconditions.json")); cr = json.load(open(f"{ROOT}/coarse/coarse_record.json")); pr = json.load(open(f"{ROOT}/predictors/predictors_record.json")); tg = json.load(open(f"{ROOT}/targets/targets_record.json"))
    gb = json.load(open(f"{ROOT}/gbt/record.json")); res = json.load(open(f"{ROOT}/scores/results.json")); PP = pd.read_csv(f"{ROOT}/scores/per_pair.csv"); main = res["main_variant"]; other = [v for v in ("cfg18", "frozen_fold_cfg") if v != main][0]
    # 1. preconditions
    after = git("status", "--porcelain", "--", "grl_reviews-and-prompt-reports/directives_and_reports/phase4"); out["phase4_git_status_after"] = after
    rows = [[f"`{s}`", f"`{v['on_disk'][:16]}…`", f"`{(v['b6'] or '')[:16]}…`", v["equal"]] for s, v in pre["1_scripts"].items()]
    rows += [["`git status --porcelain phase4/` before", f"`{pre['1_phase4_git_status_before'] or '(clean)'}`", "", ""], ["`git status --porcelain phase4/` after", f"`{after or '(clean)'}`", "", pre["1_phase4_git_status_before"] == after == ""], ["R09 guard self-test", f"{pre['guard']['blocked']} / {pre['guard']['probes']}", "", pre["2_passed"]], ["git HEAD at the preconditions", f"`{pre['git_head'][:12]}`", "", ""]]
    write("preconditions.md", md(rows, ["item", "on disk", "v2.1 B6 table", "equal / passed"]), "from tables/preconditions.json and git")
    rows = [[r["pair"], r["unit"], f"{r['hr_res']:.3f}", f"{r['lr_native']:.2f}", r["k"], r["D1"], f"{r['cells_native']:.2f}", r["status_r10"], r["view_r10"], f3(r["rho_s_lr_r10"]), f3(r["rho_GBT_r10"]), ", ".join(f"{c:g}" for c in r["levels"]) or "—", ", ".join(f"{c:g}" for c in r["skipped"]) or "—"] for r in pre["3_pairs"]]
    rows.append([f"**C1-set pairs: {pre['3_n_c1']}** (s_lr CI lower bound > 0 on {pre['3_n_pass_r10']})", "", "", "", "", "", "", "", "", "", "", "", ""])
    write("pairs.md", md(rows, ["pair", "unit", "hr_res (m)", "lr_native (m)", "k", "D₁ (px)", "native cells across", "R10 status", "R10 view", "ρ s_lr (R10)", "ρ GBT_ship (R10)", "levels reached", "levels skipped (lr_target ≤ lr_native)"]), "from tables/preconditions.json (R10b per_pair_D1.csv, tiles_v1.1)")
    # 2. coarse grids
    rows = []
    for pid, r in cr["pairs"].items():
        for c in LEVELS:
            l = r["levels"].get(str(c))
            if l is None: rows.append([pid, f"{c:g}", "skipped", f"{r['skipped'][str(c)]:.2f} ≤ {r['lr_native']:.2f}", "", "", "", "", "", ""]); continue
            rows.append([pid, f"{c:g}", f"{l['lr_target']:.2f}", f"{l['ratio_s']:.3f}", l["lr_px_frozen_path"], f"{l['coarse_shape'][0]} × {l['coarse_shape'][1]}", l["n_coarse_valid"], f"{l['coverage_median_valid']:.3f}", l["products"], f"`{l['files']['lr.tif'][:12]}…` / `{l['files']['lr_valid.tif'][:12]}…`"])
    rows.append([f"**{cr['n_rasters']} rasters**, sha256 in `coarse/SHA256SUMS_coarse.txt`; method: {cr['method']}", "", "", "", "", "", "", "", "", ""])
    write("coarse.md", md(rows, ["pair", "level (cells across)", "lr_target (m)", "ratio to native posting", "lr_px of the frozen path", "coarse grid", "valid coarse cells", "median coverage of valid cells", "products", "sha256 lr.tif / lr_valid.tif"]), "from coarse/coarse_record.json (coarsen_r14.py)")
    # 3. native checks
    rows = []
    for pid, r in pr["pairs"].items():
        c = r["native"]["check"]; t = tg["pairs"][pid]["check"]
        rows.append([pid, r["n_tiles"], c["s_lr_identical"], f"{c['s_lr_max_abs_diff']:.1e}", f"{c['features_max_abs_diff']:.2e}", c["features_nan_pattern_identical"], c["features_within_1e6"], ", ".join(f"{k} {v:.1e}" for k, v in c["columns_above_1e9"].items()) or "none", t["joint_identical"], f"{t['F_hr_max_abs_diff']:.1e}", f"{t['A_fine_max_abs_diff']:.1e}" + (" (identical)" if t["A_fine_identical"] else ""), t["interior_D1_identical"], f"{t['A_fine_int_D1_max_abs_diff']:.1e}" + (" (identical)" if t["A_fine_int_D1_identical"] else "")])
    write("native_checks.md", md(rows, ["pair", "tiles", "s_lr identical", "max \\|Δ s_lr\\|", "features max \\|Δ\\| (bar_v1_1.ALL)", "NaN pattern identical", "within 1e-6", "columns above 1e-9", "joint crops identical", "F_hr max \\|Δ\\| (m)", "A_fine max \\|Δ\\| (m)", "interior flag D₁ identical", "A_fine_int D₁ max \\|Δ\\| (m)"]), "from predictors/*/record.json and targets/*/record.json (native level vs tiles_v1.1, features_v1.parquet, R04 fields, R09 tiles_int via the R10b inputs); the F_hr / A_fine differences are float32 FFT round-off across CPU generations (R10 HOLD H3)")
    # 4. GBT folds
    rows = []
    for v in ("cfg18", "frozen_fold_cfg"):
        V = gb["variants"][v]; tc = V["tile_comparison_vs_frozen"]
        for pid, r in V["per_pair"].items():
            if "abs_diff" in r: rows.append([v, pid, r["unit"], r["cfg_idx_fold"], r["view"], r["n"], f3(r["rho_refit"]), f3(r["rho_frozen_r10b"]), f"{r['abs_diff']:.4f}", r["within_0p01"]])
        rows.append([f"**{v}**", f"tiles vs frozen held-out predictions: max \\|Δ\\| {tc['max_abs_diff_m']:.2e} m (n {tc['n']})", "", "", "", "", "", "", f"max {V['max_abs_rho_diff']:.4f}", f"**{V['n_within_0p01']} of {V['n_pairs']}**"])
    rows.append([f"main variant used for the `GBT_ship` column: **{main}** — {gb['main_variant_note']}; frozen bar fold configurations: " + ", ".join(f"{u} {c}" for u, c in gb["reproduction_bar"]["frozen_bar_fold_cfgs"].items()) + f"; folds using cfg 18: {gb['reproduction_bar']['n_frozen_folds_using_cfg18']}", "", "", "", "", "", "", "", "", ""])
    write("gbt_folds.md", md(rows, ["variant", "pair", "unit", "fold cfg idx", "R10 view", "n", "ρ refit (native, out of unit)", "ρ frozen (R10b)", "\\|Δρ\\|", "within 0.01"]), "from gbt/record.json (gbt_folds_r14.py): leave-one-unit-out refits on native features vs the frozen held-out GBT_ship")
    # 5. main tables
    def main_table(analysis):
        rows = []
        for k in KEYS:
            S = res["analyses"][analysis].get(k)
            if S is None: continue
            ps, pg, po = S["pooled"]["s_lr"], S["pooled"][f"GBT_ship__{main}"], S["pooled"][f"GBT_ship__{other}"]; ref = S.get("pooled_frozen_same_pairs") or {}
            rows.append([LABEL[k], f"{S['n_pairs_reached']} / {S['n_pairs_scored']}" + (f" (not scorable {S['n_not_scorable']})" if S["n_not_scorable"] else ""), pooled_str(ps), f"{S['n_lower_gt0_s_lr']} of {S['n_pairs_scored']}", pooled_str(pg), f"{S[f'n_lower_gt0_GBT__{main}']} of {S['n_pairs_scored']}", pooled_str(po), f"{S[f'n_lower_gt0_GBT__{other}']} of {S['n_pairs_scored']}",
                         (f"{S['frac_undefined']:.3f} / {S['frac_floor']:.3f}" if np.isfinite(S["frac_undefined"]) else "—"), (f"{S['frac_undefined_view']:.3f} / {S['frac_floor_view']:.3f}" if np.isfinite(S["frac_undefined_view"]) else "—"), pooled_str(ref.get("s_lr")), pooled_str(ref.get(f"GBT_ship__{main}"))])
        return md(rows, ["level (ship cells across)", "pairs reached / scored", "s_lr pooled mean ρ [95 % CI]", "s_lr: pairs with CI lower > 0", f"GBT_ship ({main}) pooled ρ [95 % CI]", f"GBT_ship ({main}): lower > 0", f"GBT_ship ({other}) pooled ρ [95 % CI]", f"GBT_ship ({other}): lower > 0", "s_lr undefined / floored (all tiles of scored pairs)", "s_lr undefined / floored (view tiles)", "frozen native s_lr pooled, same pairs", f"frozen native GBT_ship pooled, same pairs"])
    write("main_primary.md", main_table("primary"), "from scores/results.json (score_r14.py; primary analysis: frozen target, tile set, interior view and blocks; ship side replaced)")
    write("main_secondary.md", main_table("secondary"), "from scores/results.json (score_r14.py; secondary analysis: band lower edge hr_res / lr_target, frozen upper edge, D1 = ceil(lr_target / hr_res), frozen B4 view rules)")
    # 6. per-pair tables
    def per_pair(analysis):
        P = PP[(PP.analysis == analysis) & (~PP.skipped.astype(bool))]; rows = []
        for pid in pre["3_c1_set"]:
            g = next(r for r in pre["3_pairs"] if r["pair"] == pid)
            for k in KEYS:
                r = P[(P.pair == pid) & (P.level == k)]
                if len(r) == 0: rows.append([pid, g["unit"], f"{g['cells_native']:.2f}", LABEL[k], "skipped", "", "", "", "", "", "", ""]); continue
                r = r.iloc[0].to_dict()
                rows.append([pid, g["unit"], f"{g['cells_native']:.2f}", LABEL[k], f"{r['cells_across']:.2f}", r["view"], r["n_scored"], f"{f3(r['rho_s_lr'])} {ci(r, 'ci_lo_s_lr', 'ci_hi_s_lr')}", "yes" if r["lower_gt0_s_lr"] else "no", f"{f3(r[f'rho_GBT__{main}'])} {ci(r, f'ci_lo_GBT__{main}', f'ci_hi_GBT__{main}')}", "yes" if r[f"lower_gt0_GBT__{main}"] else "no", f"{f3(r[f'rho_GBT__{other}'])} {ci(r, f'ci_lo_GBT__{other}', f'ci_hi_GBT__{other}')}", f"{int(r['n_s_lr_undefined_pair'])} / {int(r['n_s_lr_floor_pair'])} of {int(r['n_tiles_pair'])}", r["status"]])
        return md(rows, ["pair", "unit", "native cells across", "level", "cells across at the level", "view", "n scored", "ρ s_lr [95 % CI]", "s_lr lower > 0", f"ρ GBT_ship ({main}) [95 % CI]", f"GBT ({main}) lower > 0", f"ρ GBT_ship ({other}) [95 % CI]", "s_lr undefined / floored tiles", "status"])
    write("per_pair_primary.md", per_pair("primary"), "from scores/per_pair.csv (score_r14.py; primary analysis)")
    write("per_pair_secondary.md", per_pair("secondary"), "from scores/per_pair.csv (score_r14.py; secondary analysis)")
    # 7. secondary views
    rows = []
    for pid in pre["3_c1_set"]:
        t = tg["pairs"][pid]; cells = [pid, t["unit"]]
        for k in KEYS[1:]:
            b = t["bands"].get(k); v = t["views"].get(k); r = PP[(PP.analysis == "secondary") & (PP.pair == pid) & (PP.level == k) & (~PP.skipped.astype(bool))]
            cells.append("skipped" if b is None else f"D₁ {b['D1_px']} px; f_lr {b['f_lr']:.4f}; int {v['n_interior']} / fb {v['n_fallback']} → **{r.iloc[0]['view'] if len(r) else '?'}** ({int(r.iloc[0]['n_scored']) if len(r) else 0})")
        rows.append(cells)
    write("views_secondary.md", md(rows, ["pair", "unit"] + [LABEL[k] for k in KEYS[1:]]), "from targets/*/record.json and scores/per_pair.csv: band lower edge, D1' and the B4 view in use per level (interior tiles / tiles with A_fine_int defined → view (n scored)); the frozen upper edge is the pair's f_hi")
    # 8. expectations (§1), exact definitions
    def ev(analysis):
        Pm = res["analyses"][analysis]; nat_full = Pm["frozen" if analysis == "primary" else "native"]["pooled"]; E = []
        for k in ("c2.1", "c1.7"):
            S = Pm[k]; ps = S["pooled"]["s_lr"]; pg = S["pooled"][f"GBT_ship__{main}"]; ref = S["pooled_frozen_same_pairs"]
            lo_le0 = bool(ps and ps["estimable"] and ps["ci95"][0] <= 0) or bool(ps and not ps["estimable"])
            drop_full = (nat_full["s_lr"]["mean_rho"] - ps["mean_rho"]) if ps else np.nan; drop_same = (ref["s_lr"]["mean_rho"] - ps["mean_rho"]) if (ps and ref and ref["s_lr"]) else np.nan
            e1 = bool(lo_le0 or (np.isfinite(drop_same) and drop_same >= 0.20)); e2 = bool(pg and pg["estimable"] and pg["ci95"][0] > 0)
            gdrop_same = (ref[f"GBT_ship__{main}"]["mean_rho"] - pg["mean_rho"]) if (pg and ref and ref.get(f"GBT_ship__{main}")) else np.nan
            E.append(dict(level=k, n_pairs=S["n_pairs_scored"], s_lr_pooled=ps, s_lr_lower_le0=lo_le0, drop_vs_frozen_all14=drop_full, drop_vs_frozen_same_pairs=drop_same, expectation1=e1, gbt_pooled=pg, gbt_lower_gt0=e2, expectation2=e2, gbt_drop_vs_frozen_same_pairs=gdrop_same,
                          expectation3=bool((not e1) and not (np.isfinite(gdrop_same) and gdrop_same >= 0.20) and not (pg and pg["estimable"] and pg["ci95"][0] <= 0))))
        return E
    out["expectations"] = {a: ev(a) for a in ("primary", "secondary")}
    rows = []
    for a, E in out["expectations"].items():
        for e in E:
            rows.append([a, LABEL[e["level"]], e["n_pairs"], pooled_str(e["s_lr_pooled"]), "yes" if e["s_lr_lower_le0"] else "no", f"{e['drop_vs_frozen_same_pairs']:+.3f} (vs all 14: {e['drop_vs_frozen_all14']:+.3f})", "**matched**" if e["expectation1"] else "not matched", pooled_str(e["gbt_pooled"]), "yes" if e["gbt_lower_gt0"] else "no", "**matched**" if e["expectation2"] else "not matched", f"{e['gbt_drop_vs_frozen_same_pairs']:+.3f}", "**matched**" if e["expectation3"] else "not matched"])
    write("expectations.md", md(rows, ["analysis", "level", "pairs", "s_lr pooled ρ [CI]", "s_lr CI lower ≤ 0 (or not estimable)", "s_lr drop from the frozen native pooled (same pairs)", "§1.1 (coarse sampling explains): lower ≤ 0 OR drop ≥ 0.20", "GBT_ship pooled ρ [CI]", "GBT CI lower > 0", "§1.2 (GBT keeps lower > 0)", "GBT drop (same pairs)", "§1.3 (neither degrades materially: no §1.1, GBT drop < 0.20 and GBT lower > 0)"]), "from scores/results.json: the §1 expectations under their exact definitions, at 2.1 and 1.7 cells across (the directive names 'pooled s_lr at 1.7 to 2.1 cells across'); 'drop' = frozen native pooled mean over the same pairs minus the level's pooled mean")
    out["must_hold_5_4"] = res["must_hold_5_4"]; out["main_variant"] = main
    json.dump(out, open(f"{TABLES}/tables.json", "w"), indent=1, default=str); print("tables written:", sorted(os.listdir(TABLES)))
